using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class UgoAudit{
const string Work=@"C:\Users\user\Desktop\02_Справочники_CAD_Revit\odnolineyka\_Разработка\ugo";
static string Name(BlockReference b,Transaction t)=>((BlockTableRecord)t.GetObject(b.IsDynamicBlock?b.DynamicBlockTableRecord:b.BlockTableRecord,OpenMode.ForRead)).Name;
static object Ext(Entity e){try{var x=e.GeometricExtents;return new{Min=new[]{x.MinPoint.X,x.MinPoint.Y},Max=new[]{x.MaxPoint.X,x.MaxPoint.Y}};}catch{return null;}}
static object Block(BlockReference b,Transaction t){var attrs=new Dictionary<string,string>();foreach(ObjectId id in b.AttributeCollection){var a=(AttributeReference)t.GetObject(id,OpenMode.ForRead);attrs[a.Tag]=a.TextString;}var props=new Dictionary<string,string>();if(b.IsDynamicBlock)foreach(DynamicBlockReferenceProperty p in b.DynamicBlockReferencePropertyCollection)props[p.PropertyName]=p.Value?.ToString();var def=(BlockTableRecord)t.GetObject(b.BlockTableRecord,OpenMode.ForRead);return new{Handle=b.Handle.ToString(),Name=Name(b,t),Actual=def.Name,Layer=b.Layer,Xref=def.IsFromExternalReference,Position=new[]{b.Position.X,b.Position.Y},Scale=new[]{b.ScaleFactors.X,b.ScaleFactors.Y},Rotation=b.Rotation,Extents=Ext(b),Attributes=attrs,Properties=props};}
[CommandMethod("CODEXUGOAUDIT",CommandFlags.Session)]public void Run(){try{var added=JsonDocument.Parse(File.ReadAllText(Path.Combine(Work,"added.json")));var target=added.RootElement.GetProperty("File").GetString();var inspection=JsonDocument.Parse(File.ReadAllText(Path.Combine(Work,"../ssm_task/inspection.json")));var set=inspection.RootElement.EnumerateArray().Single(s=>s.GetProperty("Title").GetString()=="Подшивка_ELF-D1-02-ЭОМ");var plans=set.GetProperty("Sheets").EnumerateArray().Select(s=>s.GetProperty("File").GetString()).Distinct(StringComparer.OrdinalIgnoreCase).Where(f=>Path.GetFileName(f).StartsWith("03_")).ToArray();var output=new List<object>();foreach(var file in plans.Concat(new[]{target})){var doc=AcApp.DocumentManager.Cast<Autodesk.AutoCAD.ApplicationServices.Document>().FirstOrDefault(d=>string.Equals(d.Name,file,StringComparison.OrdinalIgnoreCase));Database db=doc?.Database;bool own=db==null;if(own){db=new Database(false,true);db.ReadDwgFile(file,FileOpenMode.OpenForReadAndAllShare,true,null);db.CloseInput(true);}try{using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var model=(BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);var blocks=new List<object>();var curves=new List<object>();var texts=new List<object>();foreach(ObjectId id in model){if(tr.GetObject(id,OpenMode.ForRead) is not Entity e)continue;if(e is BlockReference b)blocks.Add(Block(b,tr));else if(e is Curve c)curves.Add(new{Type=e.GetType().Name,e.Layer,e.Linetype,Handle=e.Handle.ToString(),Extents=Ext(e)});else if(e is MText m)texts.Add(new{e.Layer,Text=m.Text,Handle=e.Handle.ToString(),Extents=Ext(e)});else if(e is DBText d)texts.Add(new{e.Layer,Text=d.TextString,Handle=e.Handle.ToString(),Extents=Ext(e)});}
var papers=new List<object>();var ld=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);foreach(DBDictionaryEntry entry in ld){var l=(Layout)tr.GetObject(entry.Value,OpenMode.ForRead);if(l.ModelType)continue;var paper=(BlockTableRecord)tr.GetObject(l.BlockTableRecordId,OpenMode.ForRead);var objs=new List<object>();foreach(ObjectId id in paper){if(tr.GetObject(id,OpenMode.ForRead) is not Entity e)continue;if(e is BlockReference b)objs.Add(Block(b,tr));else if(e is Table tab){var rows=new List<object>();for(int r=0;r<tab.Rows.Count;r++)rows.Add(new{Index=r,Height=tab.Rows[r].Height,Cells=Enumerable.Range(0,tab.Columns.Count).Select(c=>tab.Cells[r,c].TextString).ToArray()});objs.Add(new{Type="Table",Handle=e.Handle.ToString(),Position=new[]{tab.Position.X,tab.Position.Y},Extents=Ext(e),Rows=rows});}else if(e is Viewport v)objs.Add(new{Type="Viewport",Number=v.Number,Center=new[]{v.ViewCenter.X,v.ViewCenter.Y},v.ViewHeight,v.CustomScale});else if(e is Curve)objs.Add(new{Type=e.GetType().Name,Handle=e.Handle.ToString(),e.Layer,Extents=Ext(e)});}papers.Add(new{Layout=l.LayoutName,Objects=objs});}output.Add(new{File=file,Live=doc!=null,Blocks=blocks,Curves=curves,Texts=texts,Papers=papers});}}finally{if(own)db.Dispose();}}
File.WriteAllText(Path.Combine(Work,"hbk_audit.json"),JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));}catch(System.Exception e){File.WriteAllText(Path.Combine(Work,"audit_error.txt"),e.ToString());}}
}
